import{F as e,I as t,Z as n,t as r}from"./chunks/framework.BdlpXgFt.js";var i=JSON.parse(`{"title":"项目纪律","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/deep-dive/discipline.md","filePath":"zh-Hans/deep-dive/discipline.md","lastUpdated":1795199667000}`),a={name:`zh-Hans/deep-dive/discipline.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="项目纪律" tabindex="-1">项目纪律 <a class="header-anchor" href="#项目纪律" aria-label="Permalink to “项目纪律”">​</a></h1><h2 id="数据规范化" tabindex="-1">数据规范化 <a class="header-anchor" href="#数据规范化" aria-label="Permalink to “数据规范化”">​</a></h2><p>数据规范化指把来自外部源的数据转换成 Sync Engine 内部使用的规范形式。</p><ul><li>对&quot;不可靠&quot;的条目（用户输入，或由众多服务器实现的标准），所有需要规范化的数据必须在入口点精确地、且仅一次地完成规范化。Sync Engine 内部不应再做任何规范化。</li><li>对&quot;可靠&quot;的条目（由单一供应商实现的专有 API），完全不应做规范化。</li></ul><p>特殊数据分为以下几类，无论来源可靠性如何都必须规范化：</p><ul><li>文件大小：转换为字节数的单一数字。面向用户的展示转换为数字 + 空格 + 大写单位，例如 <code>1 GB</code>、<code>537 MB</code>、<code>29.9 KB</code>，以 1024 为基数（严格来说单位是 <code>KiB</code>/<code>MiB</code>/...，但为便于理解使用不带 <code>i</code> 的单位），最多 2 位小数。</li><li>时间长度：毫秒精度的整数 Unix 时间戳。面向用户的展示使用数字 + 空格 + 小写单位，例如 <code>1 s</code>、<code>24 h</code>、<code>2.3 d</code>，最多 2 位小数。</li><li>文件路径（键）：遵循<a href="./file-system#统一键模式">统一键</a>——<code>folder/file.ext</code>，文件夹 - <code>folder/nested/</code>，根：<code>/</code>。规范化为 Unicode NFC。</li><li>URL：所有 URL 的路径名、查询参数和片段按 RFC 3986 百分号编码；协议和主机名中的 ASCII 拉丁字母转为小写。面向用户的展示对路径名、查询参数和片段做解码。</li><li>请求 / 响应头键：尽可能使用 kebab-case。用户自定义的键保留原大小写。</li><li>ETag：剥离 <code>W/</code> 弱 ETag 标记和两侧引号。</li></ul><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to “文档”">​</a></h2><ul><li>主文档位于 <code>docs/src/pages/en/</code>，分三个文件夹对应三个部分：<code>usage/</code>、<code>development/</code> 和 <code>deep-dive/</code>： <ul><li><code>usage/</code>：面向非技术用户，避免行话</li><li><code>development/</code>：只放 SDK API 参考和实用的模块开发设置</li><li><code>deep-dive/</code>：Sync Engine 内部机制</li></ul></li><li>其他页面有相关内容时优先使用页面间链接，禁止跨页重复内容。</li><li>链接格式：尽可能链接标题锚点，严格的相对链接，不带 <code>.md</code> 扩展名。</li><li>只在内容真正相关时添加页间链接，不得为了链接数量而链接远处的页面。</li><li>链接拓扑： <ul><li><code>usage/</code> 和 <code>deep-dive/</code> 可以互链</li><li><code>development/</code> 可以链接到 <code>usage/</code> 和 <code>deep-dive/</code>，但 <code>usage/</code> 和 <code>deep-dive/</code> 应避免链接进 <code>development/</code>。</li><li>模块规范（<code>deep-dive/modules/*</code>）应在各自页面内自包含。它们可以链接外部页面，但外部页面不应链接官方模块，<code>usage/</code> 中的专门页面除外。</li></ul></li><li>不要过度冗长。</li><li><code>usage/</code> 和 <code>deep-dive/</code> 避免大段代码，代码应作为 <code>development/</code> 的主体内容。</li><li>文档标题使用 title case。</li></ul><h2 id="代码风格" tabindex="-1">代码风格 <a class="header-anchor" href="#代码风格" aria-label="Permalink to “代码风格”">​</a></h2><ul><li>只允许 JSDoc 注释硬换行（在句子中间断行）。</li><li>其他注释首选单行。需要多行时，每行必须是完整的句子。</li><li>注释行可以超出打印宽度限制。</li><li>能提升简洁性时优先使用解构。</li></ul>`,10)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};